mapper.select:
SELECT TO_CHAR(T.UPTIME, 'YYYY') AS YEAR, T.EQUIPTCATEGORY, SUM(T.AMOUNT) AS AMOUNT FROM T_CORE_EQUIPT_USAGE_RECORD T WHERE TO_DATE (TO_CHAR(T.UPTIME, 'YYYY'), 'YYYY') BETWEEN TO_DATE (#{startYear}, 'YYYY') AND TO_DATE (#{endYear}, 'YYYY')
AND T.EQUIPTCATEGORY = #{equiptCategory}
GROUP BY T.EQUIPTCATEGORY, TO_CHAR(T.UPTIME, 'YYYY')
